<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Requests\ActivateSubscriptionRequest; use App\Models\{SubscriptionPackage,UserSubscription}; use App\Support\ApiResponse; use Illuminate\Support\Facades\DB;
class SubscriptionController extends Controller {use ApiResponse; public function show(){return response()->json(['subscription'=>request()->user()->subscription?->load('package')]);} public function packages(){return response()->json(['packages'=>SubscriptionPackage::where('is_active',1)->orderBy('sort_order')->get()]);} public function activate(ActivateSubscriptionRequest $r){$package=SubscriptionPackage::findOrFail($r->package_id);$s=DB::transaction(function()use($r,$package){$r->user()->userSubscriptions()->where('status','active')->update(['status'=>'cancelled','cancelled_at'=>now()]);return $r->user()->userSubscriptions()->create(['subscription_package_id'=>$package->id,'status'=>'active','started_at'=>now(),'expiry_date'=>today()->addDays($package->duration_days)]);});return $this->success($s->load('package'),'Subscription activated successfully.',201);} public function cancel(){ $s=request()->user()->userSubscriptions()->where('status','active')->latest()->first();abort_unless($s,422,'No active subscription found.');$s->update(['status'=>'cancelled','cancelled_at'=>now()]);return $this->success($s->fresh()->load('package'),'Subscription cancelled successfully.');}}
